const universityCourse=courses.find(course=>course.id==='university');
universityCourse.duration='Twenty applied AI and Python projects';
universityCourse.summary='Explore speech, language, computer vision, and machine learning through practical Python projects and responsible experiments.';
universityCourse.outcomes=['Prepare small, documented datasets and choose suitable AI tools','Build and evaluate speech, language, vision, and learning workflows','Explain model uncertainty, limitations, and accessibility considerations','Protect privacy and test systems fairly before sharing results'];
const universityProjectSectionTitles=['Project introduction','Learning objectives','Tools and data','Data workflow and connections','Python programming workspace','Step-by-step instructions','Code explanations','Testing and responsible use','Challenge activity'];
const universityProjectSpecs=[
 ['Speech Recognition','Turn a short spoken recording into text using a speech-recognition model.','A short, consented audio sample; a compatible speech-recognition model; a Python audio-processing environment.','Audio file → check duration and format → run speech recognition → review transcript → save only with permission.','from pathlib import Path\n\naudio_path = Path("sample.wav")\ntranscript = recognize_speech(audio_path)\nprint(transcript)','speech','Check recognition with a quiet recording and a noisy one. Compare errors across accents and speaking speeds.','Add a confidence display and let the speaker correct the transcript before it is used.'],
 ['Translate Text','Translate a short sentence and compare the result with its original meaning.','A public or consented sentence; an approved translation model or service; a source and target language.','Text → choose source and target languages → translate → review wording and uncertainty → share only with permission.','sentence = "Good morning, everyone."\ntranslated = translate_text(sentence, source="en", target="fr")\nprint(translated)','text','Try idioms and short factual sentences. Check meaning with a fluent speaker; machine translation can be wrong.','Compare two target languages and write down where context changes the translation.'],
 ['Text Analysis','Analyze a small text sample for word patterns, keywords, or sentiment.','A short public or consented text sample; a tokenizer or analysis library; a written output summary.','Text → remove accidental personal data → tokenize → analyze → inspect examples behind the result.','text = "Robots can help people learn."\nwords = tokenize(text)\nprint(word_counts(words))','text','Use examples with different wording, spelling, and tone. Check whether the summary matches the source.','Compare two analysis methods and document where each gives an unhelpful result.'],
 ['Face Detection','Locate faces in an image without identifying who the people are.','A consented image or test image; a face-detection model; image display and bounding-box overlay.','Image → check consent → detect face regions → draw boxes → discard the image when finished.','image = load_image("consented_sample.jpg")\nboxes = detect_faces(image)\nshow_boxes(image, boxes)','vision','Test different lighting, face sizes, and angles. Record missed detections and false boxes.','Add a minimum-size filter and explain how it changes missed and false detections.'],
 ['Face Detection · Live Camera','Detect face regions in a short live camera preview without identifying people.','A camera with a visible on indicator; a consented participant or test setup; a face-detection model; a stop control.','Camera frame → detect face regions → draw boxes → display preview briefly → stop and release camera.','camera = open_camera()\nfor frame in camera:\n    show_boxes(frame, detect_faces(frame))\ncamera.release()','vision','Check that camera permission is requested, the preview stops on command, and frames are not saved.','Add a clear camera-on notice and measure detection delay without recording video.'],
 ['Voice Command Detection','Recognize a small set of spoken commands and map them to safe actions.','Consented command recordings; a speech model; a short command vocabulary; a simulated action target.','Audio → recognize words → match an allowed command → show confirmation → run only a safe simulated action.','command = recognize_command("turn left")\nif command in ALLOWED_COMMANDS:\n    simulate(command)','speech','Test quiet, noisy, and unfamiliar speech. Confirm unknown commands do not trigger an action.','Add a confidence threshold and a confirmation step before running a command.'],
 ['Object Detection','Find and label selected object categories in an image or video frame.','Public or consented images; a compatible object-detection model; labels and confidence scores.','Frame → detect candidate objects → filter by confidence → display boxes and labels.','detections = detect_objects(frame)\nfor item in detections:\n    if item.confidence >= 0.6:\n        draw_box(frame, item)','vision','Use images with different backgrounds and object sizes. Track false positives and missed objects.','Compare two confidence thresholds and explain the trade-off using a small results table.'],
 ['Image Classifier','Classify an image into a small set of clearly defined categories.','A balanced, labeled image set; an image-classification model; separate training and evaluation examples.','Image → resize and normalize → classify → show top predictions → compare with the correct label.','scores = classify_image(image)\nlabel = max(scores, key=scores.get)\nprint(label, scores[label])','vision','Evaluate on images not used to train or tune the model. Review errors by category.','Add a category and test whether the model confuses it with an existing class.'],
 ['Machine Learning','Train and evaluate a simple model on a small tabular dataset.','A documented dataset; input features and target labels; a train/test split; a suitable Python ML library.','Dataset → inspect columns → split examples → train model → evaluate on held-out data.','X_train, X_test, y_train, y_test = split_data(X, y)\nmodel.fit(X_train, y_train)\nprint(model.score(X_test, y_test))','ml','Compare training and test scores. Check for leakage, imbalance, and mislabeled examples.','Change one feature or model setting and compare test results fairly.'],
 ['Neural Network','Train a small neural network and examine how its predictions change.','A small labeled dataset; a neural-network library; normalized input data; held-out evaluation examples.','Data → normalize → define a small network → train → evaluate → inspect incorrect predictions.','model = make_small_network(input_size, classes)\nmodel.fit(X_train, y_train, epochs=5)\nprint(evaluate(model, X_test, y_test))','ml','Compare training and evaluation results. Look for overfitting and repeat with a fixed random seed.','Change one network setting at a time and record accuracy and training time.'],
 ['Read Text Aloud','Create an accessible read-aloud tool with a clear play, pause, and stop flow.','Text with headings and punctuation; a speech engine; playback controls; optional pronunciation dictionary.','Text → split into readable sentences → synthesize line by line → play, pause, resume, or stop.','for sentence in split_sentences(article_text):\n    play_or_queue(text_to_speech(sentence))','speech','Try punctuation, abbreviations, and long paragraphs. Check that pause and resume work as expected.','Add a highlight for the sentence being read and a control for speech speed.'],
 ['Gesture Detection','Recognize a small set of agreed gestures from a camera stream.','A camera; consented gesture examples; a hand-pose or gesture model; a visible camera-on indicator.','Camera frame → detect landmarks → classify agreed gesture → display result → stop capture when requested.','landmarks = detect_hand_landmarks(frame)\ngesture = classify_gesture(landmarks)\nshow_label(gesture)','vision','Test each gesture at different distances and backgrounds. Include a no-gesture case.','Add a “not sure” state and measure how often it prevents incorrect labels.'],
 ['Hand Detection','Locate hands and display their positions without identifying a person.','Consented camera input or test images; a hand-detection model; landmark visualization.','Frame → detect hand regions → find landmarks → overlay points → release camera when finished.','hands = detect_hands(frame)\nfor hand in hands:\n    draw_landmarks(frame, hand.landmarks)','vision','Test one hand, two hands, partial views, and no hand. Note missed and false detections.','Track one landmark over time and plot its movement without storing video.'],
 ['Facial Analysis','Study face-region measurements as a computer-vision exercise without inferring identity.','Consented test images; face landmarks; a documented measurement method; local-only processing.','Image → detect face → estimate landmarks → calculate a limited geometric measurement → show uncertainty.','landmarks = face_landmarks(image)\nmeasurements = face_geometry(landmarks)\nprint(measurements)','vision','Check how lighting, angle, and image resolution change landmark positions. Do not treat measurements as facts about a person.','Compare landmark stability across several consented poses and report uncertainty.'],
 ['Facial Expression Classification','Classify visible expression categories as an uncertain model output, not a fact about feelings.','Consented or public test images; an expression model; clearly labeled categories; privacy-safe storage.','Image → detect face → estimate expression class → show confidence and limitations → delete source if not needed.','scores = classify_expression(face_crop)\nprint(sorted(scores.items(), key=lambda item: item[1], reverse=True))','vision','Test varied lighting, pose, and skin tones. Discuss false results and why expressions do not reveal a person’s true feelings.','Create a safe-use guide explaining where expression classification should not be used.'],
 ['Face Mesh','Visualize facial landmark points on a consented image or live preview.','A consented test image; a face-mesh model; a drawing overlay; camera privacy controls if live.','Image/frame → estimate mesh landmarks → draw points → show preview → stop and release input.','mesh = estimate_face_mesh(frame)\npreview = draw_mesh(frame, mesh)\nshow(preview)','vision','Test front-facing and turned faces. Check alignment and stop the camera after the activity.','Compare landmark counts and stability for still images and short live samples.'],
 ['Pose Detection','Estimate body landmarks in an image or video and visualize their positions.','Consented test image or video; a pose-estimation model; a visible privacy notice; local processing where possible.','Frame → estimate pose landmarks → draw skeleton → show confidence → discard frames after use.','pose = estimate_pose(frame)\nif pose.confidence > 0.5:\n    draw_pose(frame, pose.landmarks)','vision','Test full-body, partial-body, and empty scenes. Record when landmarks disappear or jump.','Use landmark coordinates to estimate one simple motion, showing confidence and limits.'],
 ['Selfie Segmentation','Separate a person region from the background for an on-device visual effect.','Consented test image or live camera; a segmentation model; background image; camera stop control.','Frame → create person mask → combine person foreground and background → preview → release camera.','mask = segment_person(frame)\nresult = blend(frame, background, mask)\nshow(result)','vision','Test different backgrounds, lighting, hair, and clothing. Look for edge artifacts and missed regions.','Add a blur background option and compare its edges with a replacement background.'],
 ['Human Detection','Detect whether one or more people appear in a scene without identifying them.','Public or consented test frames; a human-detection model; confidence display; privacy-safe handling.','Frame → detect people → display count and boxes → avoid saving frames or identity data.','people = detect_people(frame)\nprint("People detected:", len(people))\ndraw_boxes(frame, people)','vision','Test empty, crowded, and partially obstructed scenes. Discuss false counts and missed people.','Add an occupancy threshold for a simulated room and test borderline cases.'],
 ['Person-Detected Event','Create an event that starts when a person is detected, using a simulation or harmless notification.','Human-detection output; a simulated event or local indicator; an explicit stop/reset control.','Frame → detect person → require stable confidence → show event → reset when the scene is clear.','if person_detected(frame, threshold=0.7):\n    show_local_notice("Person detected")\nelse:\n    clear_notice()','vision','Test brief false detections and long occlusions. Confirm the event resets and does not store images.','Add a cooldown and compare repeated alerts with and without it.']
];
universityCourse.units=[['Applied AI and Python projects · complete each before continuing',universityProjectSpecs.map(project=>project[0])]];
const universityProjectLessons=universityProjectSpecs.map(([title,intro,tools,workflow,program,art,testing,challenge])=>({title,intro,objectives:[`Explain the goal and limits of ${title.toLowerCase()}.`,'Prepare appropriate test data and run a repeatable Python workflow.','Evaluate results with examples, errors, and documented uncertainty.'],components:[['Input data',`Provides the example ${title.toLowerCase()} will process.`,tools,art],['Python environment','Runs the code and any compatible library or model.','Use the school’s approved Python environment. Package and model requirements vary; check documentation before installation.','computer'],['Result and evaluation','Displays the prediction or output and supports checking it.','Record only what is needed for the lesson; use consented or public data and remove temporary files.','display']],wiringParts:[['Input data',tools],['Processing',workflow],['Result',testing]],blockText:program,blockNotes:[`Input: ${tools}`,`Workflow: ${workflow}`,'The model output is an estimate. Check examples and confidence rather than treating a prediction as certain.','Use only data you are allowed to process; stop capture and delete temporary data when the activity ends.'],steps:[`Read the project goal and agree on the privacy and safety rules for the chosen data.`,`Prepare a small public or consented test sample and document its source.`,`Open the University Python Editor and confirm the approved environment and required model/library are available.`,`Build the workflow from the example, using a small sample first.`,`Run one test example and inspect the result rather than relying only on a summary score.`,`Repeat with a different example or condition and record what changed.`,`Fix one issue at a time, then rerun the same tests so results are comparable.`],tests:[[`${title} gives an unexpected result`,'Check the input format, model or library version, and each workflow step; compare with a small known example.'],['Results vary across examples',testing],['The project uses camera, voice, or personal data','Use consented or public samples, process locally where possible, avoid saving raw data, and stop the input when finished.']],challenge}));
