 [['ultrasonic','HC-SR04 distance sensor',['VCC','TRIG','ECHO','GND']],['led','Red LED',['Anode (+)','Cathode (−)']],['resistor','220–330 Ω resistor',['Lead 1','Lead 2']]],
 [['driver','Dual motor driver',['VM','GND','VCC','IN1','IN2','ENA','IN3','IN4','ENB']],['motor','Left geared motor',['M+','M−']],['motor','Right geared motor',['M+','M−']],['car','Car chassis + battery pack',['Battery +','Battery −']]]
