 let text=label.replace(/\s+/g,' ').trim();const nums=[...text.matchAll(/\b\d+(?:\.\d+)?\b/g)];let value=nums.length?nums[nums.length-1][0]:'';let plain=value?text.slice(0,nums[nums.length-1].index).trim()+' '+text.slice(nums[nums.length-1].index+value.length).trim():text;plain=plain.replace(/\s+/g,' ').trim();const max=small?36:41;if(plain.length>max)plain=plain.slice(0,max-1)+'…';const pill=value?`<rect x="${w-47}" y="9" width="35" height="22" rx="11" fill="#fff"/><text x="${w-29.5}" y="24" text-anchor="middle" class="block-value">${esc(value)}</text>`:'';const available=value?w-68:w-22;if(plain.length>Math.floor(available/6.3))plain=plain.slice(0,Math.max(8,Math.floor(available/6.3)-1))+'…';const cavity=shape==='control'?`<path d="M 15 36 H ${w-16} V 54 H 15 Z" fill="#000000" fill-opacity=".12"/><path d="M 15 36 H 29 C 29 43 15 43 15 36" fill="none" stroke="#000000" stroke-opacity=".1"/>`:'';
