function renderStackLines(lines){return lines.map(raw=>{const line=raw.trim();if(!line)return '';const indent=Math.min((raw.length-raw.trimStart().length)*9,35);let category='Motion',shape='statement',label=line;if(/^when\b/i.test(line)){category='Events';shape='hat';label=line.replace(/^when\s*/i,'when ')}else if(/^(change [xy] by|move |turn |glide |go to |point in direction|if on edge)/i.test(line)){category='Motion'}else if(/^(repeat|forever|if |else|while|wait until)/i.test(line)){category='Control';shape='control'}else if(/^(say|think|show|hide)/i.test(line)){category='Looks'}else if(/^(set |change )\w+/i.test(line)){category='Variables'}else if(/(touching|distance|key pressed|sensor)/i.test(line)){category='Sensing'}else if(/^(play sound|play note)/i.test(line)){category='Sound'}else if(/^(digital|servo|pin|read )/i.test(line)){category='Hardware'}else if(/^(and |or |not |is |equals)/i.test(line)){category='Operators'}if(shape==='statement')shape=shapeForBlock(label,category);return blockRow([label,category,shape],indent)}).join('')}
