function nurseryBlockSvg(raw){
 let line=raw.trim(),category='Motion',shape='statement',parts=[];
 if(/^when\b/i.test(line)){category='Events';shape='hat'}
 else if(/^(repeat|forever|if\b|wait until)/i.test(line)){category='Control';shape='control'}
 else if(/^(say|think|show|hide|next costume|switch costume|next backdrop|switch backdrop)/i.test(line)){category='Looks'}
 else if(/^(broadcast|when I receive)/i.test(line)){category='Events';shape=/^when/i.test(line)?'hat':'statement'}
 const push=(text,type='text')=>{if(text)parts.push({text,type})};
 if(/^when green flag clicked$/i.test(line)){push('when ');push('🚩','field');push(' clicked')}
 else if(/^when space key pressed$/i.test(line)){push('when ');push('space','field');push(' key pressed')}
 else if(/^when this sprite clicked$/i.test(line))push('when this sprite clicked')
 else if(/^when backdrop switches to /i.test(line)){push('when backdrop switches to ');push(line.replace(/^when backdrop switches to /i,''),'field')}
 else if(/^when loudness\s*>\s*/i.test(line)){push('when ');push('loudness','field');push(' > ');push(line.split('>').pop().trim(),'field')}
 else if(/^when I receive /i.test(line)){push('when I receive ');push(line.replace(/^when I receive /i,''),'field')}
 else if(/^broadcast /i.test(line)){push('broadcast ');push(line.replace(/^broadcast /i,''),'field')}
 else if(/^(say|think) /i.test(line)){const m=line.match(/^(say|think)\s+(["“].*?["”])(?:\s+for\s+(\d+)\s+seconds)?$/i);if(m){push(m[1]+' ');push('“ '+m[2].slice(1,-1)+' ”','speech');if(m[3]){push(' for ');push(m[3],'field');push(' seconds')}}else push(line)}
 else if(/^wait \d+ seconds$/i.test(line)){push('wait ');push(line.match(/\d+/)[0],'field');push(' seconds')}
 else if(/^repeat \d+ times$/i.test(line)){push('repeat ');push(line.match(/\d+/)[0],'field')}
 else if(/^forever$/i.test(line))push('forever')
 else if(/^if .* then$/i.test(line)){push('if ');push('◆','condition');push(' then')}
 else if(/^wait until/i.test(line)){push('wait until ');push('◆','condition')}
 else if(/^move (-?\d+) steps$/i.test(line)){push('move ');push(line.match(/-?\d+/)[0],'field');push(' steps')}
 else if(/^turn (?:right|left) \d+ degrees$/i.test(line)){push('turn ');push(line.match(/^turn (right|left)/i)[1]==='right'?'↻':'↺','field');push(' ');push(line.match(/\d+/)[0],'field');push(' degrees')}
 else if(/^glide (\d+) secs to (.+)$/i.test(line)){const m=line.match(/^glide (\d+) secs to (.+)$/i);push('glide ');push(m[1],'field');push(' secs to ');push(m[2],'field')}
 else if(/^go to x: (-?\d+) y: (-?\d+)$/i.test(line)){const m=line.match(/x: (-?\d+) y: (-?\d+)/i);push('go to x: ');push(m[1],'field');push(' y: ');push(m[2],'field')}
 else if(/^go to /i.test(line)){push('go to ');push(line.replace(/^go to /i,''),'field')}
 else if(/^change y by /i.test(line)){push('change y by ');push(line.replace(/^change y by /i,''),'field')}
 else if(/^show$|^hide$|^next costume$|^next backdrop$/i.test(line))push(line)
 else if(/^switch backdrop to /i.test(line)){push('switch backdrop to ');push(line.replace(/^switch backdrop to /i,''),'field')}
 else push(line);
 const color={Motion:'#4c97ff',Looks:'#9966ff',Events:'#ffbf00',Control:'#ffab19'}[category]||'#4c97ff';
 let x=13,items='';for(const p of parts){const width=p.type==='field'?Math.max(27,p.text.length*6.3+14):p.type==='speech'?Math.max(64,p.text.length*5.7+16):p.type==='condition'?26:p.text.length*6.1; if(p.type==='field'||p.type==='speech'||p.type==='condition'){const fill=p.type==='speech'?'#42b849':p.type==='condition'?'#d58b12':'#d98c00';items+=`<rect x="${x}" y="11" width="${width}" height="23" rx="${p.type==='condition'?4:11}" fill="${fill}"/>`;if(p.type==='condition')items+=`<path d="M ${x+6} 22 l7 -7 h9 l7 7 -7 7 h-9z" fill="#9c610d"/>`;else items+=`<text x="${x+width/2}" y="27" text-anchor="middle" class="nursery-block-input">${esc(p.text)}</text>`}else items+=`<text x="${x}" y="27" class="nursery-block-label">${esc(p.text)}</text>`;x+=width+4}
 const width=Math.max(100,x+8),h=shape==='hat'?49:shape==='control'?67:45;let path;
 if(shape==='hat')path=`M 0 13 Q 0 6 8 6 H 22 Q 25 0 32 0 H ${width-9} Q ${width} 0 ${width} 9 V ${h-10} H 31 C 29 ${h+1} 13 ${h+1} 12 ${h-10} H 8 Q 0 ${h-10} 0 ${h-18} Z`;
 else if(shape==='control')path=`M 0 0 H 13 C 13 9 29 9 29 0 H ${width-8} Q ${width} 0 ${width} 8 V 22 H 28 C 28 29 14 29 14 22 H 13 V 48 H 28 C 28 55 14 55 14 48 H 0 Z`;
 else path=`M 0 0 H 13 C 13 9 29 9 29 0 H ${width-8} Q ${width} 0 ${width} 8 V ${h-9} H 29 C 29 ${h+1} 14 ${h+1} 14 ${h-9} H 8 Q 0 ${h-9} 0 ${h-17} Z`;
 return `<div class="nursery-block-row nursery-${category.toLowerCase()} ${shape==='control'?'nursery-c-block':''}"><svg viewBox="0 0 ${width} ${h}" role="img" aria-label="${esc(category)} block: ${esc(line)}" style="width:${width}px;height:${h}px"><path d="${path}" fill="${color}" stroke="#000" stroke-opacity=".14" stroke-width="1.2"/>${items}</svg></div>`
}
