function addBookDownloadControl(){const top=$('#book-reader .reader-top');if(!top||top.querySelector('[data-download-book]'))return;const button=document.createElement('button');button.className='book-pdf-button';button.dataset.downloadBook='';button.type='button';button.textContent='⇩ Download book';button.title='Download this complete book as a standalone HTML file';button.setAttribute('aria-label','Download this book as an HTML file');top.insertBefore(button,top.querySelector('.page-counter'))}
async function downloadBookHtml(courseId){const savedCourse=currentCourse,savedPage=currentBookPage,target=courseId?courses.find(course=>course.id===courseId):currentCourse;if(!target)return;currentCourse=target;currentBookPage=0;const lastPage=courseBookLastPage(currentCourse),pages=[];for(let page=0;page<=lastPage;page++){currentBookPage=page;renderBookPage();const source=$('#book-reader .open-book');if(source){const copy=source.cloneNode(true);copy.id=`book-page-${page}`;copy.dataset.page=String(page);pages.push(copy.outerHTML)}}currentCourse=savedCourse;currentBookPage=savedPage;if(savedCourse)renderBookPage();let css='';try{const sheet=[...document.styleSheets].find(item=>item.href&&item.href.includes('styles.css'));if(sheet)css=[...sheet.cssRules].map(rule=>rule.cssText).join('\n')}catch{}if(!css){try{const link=[...document.querySelectorAll('link[rel="stylesheet"]')].find(item=>item.href.includes('styles.css'));if(link){const response=await fetch(link.href);if(response.ok)css=await response.text()}}catch{}}const inlineBlocklyStyles=[...document.querySelectorAll('style')].map(style=>style.textContent).join('\n');css+=`\n${inlineBlocklyStyles}`;const title=`${target.title} Learning Book`, safeName=title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase(), html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${esc(target.title)} curriculum book from BuxinBloxs"><title>${esc(title)}</title><style>${css}\nbody.downloaded-book{min-width:320px;background:#eef0f5;padding:24px 14px 40px}.download-book-nav{position:sticky;z-index:5;top:10px;display:flex;justify-content:center;align-items:center;gap:18px;width:max-content;max-width:100%;margin:0 auto 16px;padding:8px 12px;border:1px solid #dfe2ed;border-radius:999px;background:#fff;box-shadow:0 5px 18px #2223}.download-book-nav button{border:0;border-radius:999px;background:#5265eb;color:#fff;padding:9px 15px;font-weight:800}.download-book-nav button:disabled{opacity:.45;cursor:default}.download-book-nav span{min-width:110px;text-align:center;color:#505874;font-size:12px;font-weight:800}.download-book-pages{max-width:900px;margin:auto}.download-book-pages .open-book{display:none;max-width:none;margin:0 auto;border-radius:6px;box-shadow:0 8px 30px #1b254022}.download-book-pages .open-book.is-current{display:block}.download-book-pages .paper-page{min-height:min(1120px,calc(100vh - 100px));margin:0 auto;border-radius:6px}.download-book-pages button[data-book-page]{cursor:pointer}@media(max-width:600px){body.downloaded-book{padding:12px 6px}.download-book-pages .paper-page{min-height:calc(100vh - 90px);padding:24px 20px}.download-book-nav{gap:8px}.download-book-nav button{padding:8px 10px}.download-book-nav span{min-width:80px}}</style></head><body class="downloaded-book"><nav class="download-book-nav" aria-label="Book pages"><button type="button" data-prev>← Previous</button><span aria-live="polite"></span><button type="button" data-next>Next →</button></nav><main class="download-book-pages">${pages.join('')}</main><script>(function(){const pages=[...document.querySelectorAll('.download-book-pages .open-book')],nav=document.querySelector('.download-book-nav'),label=nav.querySelector('span'),prev=nav.querySelector('[data-prev]'),next=nav.querySelector('[data-next]');let index=0;function show(n){index=Math.max(0,Math.min(pages.length-1,n));pages.forEach((page,i)=>page.classList.toggle('is-current',i===index));label.textContent='Page '+(index+1)+' of '+pages.length;prev.disabled=index===0;next.disabled=index===pages.length-1;window.scrollTo({top:0,behavior:'smooth'})}prev.addEventListener('click',()=>show(index-1));next.addEventListener('click',()=>show(index+1));document.addEventListener('click',event=>{const jump=event.target.closest('[data-book-page]');if(jump){event.preventDefault();show(Number(jump.dataset.bookPage))}});document.addEventListener('keydown',event=>{if(event.key==='ArrowLeft')show(index-1);if(event.key==='ArrowRight')show(index+1)});show(0)})()</script></body></html>`;const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`${safeName}.html`;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const blockRowBaseWithHardware=blockRow;
blockRow=function(item,indent=0){
 const label=String(item[0]||'');
 if(/^(turn LED pin|drive |stop motor |DC motor |ultrasonic cm|IR obstacle pin|button pin|LDR light pin|read analog pin|read digital pin|servo pin|set pin |set digital pin|set PWM pin|serial begin|serial print)/i.test(label)){
  const shape=/^(ultrasonic cm|IR obstacle pin|button pin|LDR light pin|read analog pin|read digital pin)/i.test(label)?'reporter':'statement';
  item=[label,'Hardware',shape];
 }
 return blockRowBaseWithHardware(item,indent);
};

