function lessonMarkup(course,unitIndex,lessonIndex){
 const title=course.units[unitIndex][1][lessonIndex],all=course.units.flatMap((u,ui)=>u[1].map((l,li)=>({title:l,ui,li}))),pos=all.findIndex(x=>x.ui===unitIndex&&x.li===lessonIndex),key=`${course.id}:${unitIndex}:${lessonIndex}`,done=completed.has(key),sample=sampleFor(title,course);
 currentLesson={course,unitIndex,lessonIndex,all,pos,key,title};$('#lesson-position').textContent=`${course.title} · Lesson ${pos+1} of ${all.length}`;
 const codeView=course.id==='university'||course.id==='robotics';
 $('#lesson-content').innerHTML=`<div class="lesson-hero ${course.color}"><span class="section-kicker">${esc(course.title.toUpperCase())} · ${esc(course.units[unitIndex][0])}</span><h1>${esc(title)}</h1><p>${esc(lessonIntro(title,course))}</p><div class="lesson-meta"><span>⏱ 30–45 minutes</span><span>✦ Learn by making</span><span>${esc(course.mode)}</span></div></div><div class="lesson-body"><article class="lesson-main"><h2>🎯 What you will learn</h2><ul><li>${esc(goalFor(title))}</li><li>Predict what your instructions will do before you run them.</li><li>Explain one change you made and what you observed.</li></ul><h2>💬 Warm up</h2><p>${esc(warmupFor(title))}</p><h2>🧑‍🏫 Learn the idea</h2><p>${esc(explainFor(title))}</p><h2>🛠️ Build together</h2><ol><li>Open BuxinBloxs and choose <b>${esc(course.mode.split(' → ')[0])}</b>. For hardware activities, use a simulation or the no-kit option if a board is not available.</li><li>Study the example. Read each instruction from top to bottom.</li><li>Run it in BuxinBloxs and describe what happened.</li><li>Change one value or instruction. Predict the result, then run again.</li></ol><div class="lesson-demo"><div class="lesson-demo-head"><strong>${codeView?'Python example':'Connected BuxinBloxs blocks'}</strong><span class="lesson-mode-tag">Blockly-style preview</span></div>${codeView?`<pre class="code-sample">${esc(sample)}</pre>`:`<div class="lesson-block-stack">${renderStackLines(sample.split(String.fromCharCode(10)))}</div><details class="generated-code"><summary>See the example as text</summary><pre class="code-sample">${esc(sample)}</pre></details>`}</div><h2>🧩 Your turn</h2><p>Make your own version of <b>${esc(title.toLowerCase())}</b>. Give it a clear goal. Test it more than once and make one improvement.</p><h2>🐞 Debug it</h2><p>If the result is different from your prediction, check the order of the blocks, the values you entered, and whether the program started. Change one thing at a time.</p><div class="hint-box"><b>Hint ladder:</b> 1. What should happen first? &nbsp; 2. Which block controls that action? &nbsp; 3. Compare your stack with the example, one block at a time.</div><h2>🌟 Challenge</h2><p>${esc(challengeFor(title))}</p><h2>💭 Reflect</h2><p>What did you expect? What happened? What did you change? What would you try next?</p><p class="teacher-note"><b>Teacher note:</b> Ask learners to explain the concept before helping them click through the steps. Invite different ways to demonstrate understanding.</p></article><aside class="lesson-side"><section><h3>✅ Check your understanding</h3><ul><li>What starts your program?</li><li>Which instruction makes the important change?</li><li>How could you test that it works?</li></ul></section><section><h3>🧰 You need</h3><p>BuxinBloxs in ${esc(course.mode)} mode. Optional hardware only if the teacher has confirmed the correct, safe setup.</p><p><b>No-kit option:</b> act out the instructions with picture cards or use the stage simulation.</p></section><section><h3>📚 Key words</h3><p>${esc(keyWords(title))}</p></section><section><button class="complete-button ${done?'done':''}" id="mark-complete">${done?'✓ Lesson complete':'Mark lesson complete'}</button></section></aside></div><div class="lesson-nav"><button id="previous-lesson" ${pos===0?'disabled':''}>← Previous</button><button id="next-lesson" ${pos===all.length-1?'disabled':''}>Next lesson →</button></div>`;openView('lesson');
}
function lessonIntro(title,c){return `In this lesson, we explore ${title.toLowerCase()} using ${c.mode}. Start with a prediction, make a small program, and learn from what happens.`}
function goalFor(t){if(/loop|repeat|pattern/i.test(t))return 'Recognize repetition and choose instructions that repeat.';if(/if|choice|condition|decision/i.test(t))return 'Use a condition to choose what a program does next.';if(/variable|score|counter|data/i.test(t))return 'Store and use information in a program.';if(/sensor|input|button|distance/i.test(t))return 'Use an input to help a program respond to its surroundings.';if(/debug|test|trace/i.test(t))return 'Use a prediction and a test to find and improve a program.';return `Explain and use the main idea in “${t}”.`}
function warmupFor(t){if(/move|coordinate|direction/i.test(t))return 'Stand up and describe a path from your seat to the door. Which direction will you turn? How many steps?';if(/loop|repeat|pattern/i.test(t))return 'Clap a short pattern four times. Which part repeats? Could you describe it with fewer instructions?';if(/condition|if|choice/i.test(t))return 'Think of a decision you make every day. What is the question, and what happens for each answer?';if(/sensor|input/i.test(t))return 'Name something a person can sense. What device could help a computer notice it?';return 'What do you already know about this idea? Make a prediction before you see the example.'}
function explainFor(t){return `${t} is a way to give a computer clear instructions. A program follows those instructions in order and uses the values or conditions you provide. Try to describe the idea in your own words before building.`}
function sampleFor(t,c){if(/repeat|pattern|loop/i.test(t))return 'when ▶ clicked\nrepeat 4 times\n    move 10 steps\n    turn 90 degrees';if(/if|choice|condition/i.test(t))return 'when ▶ clicked\nif touching edge?\n    turn 180 degrees\nelse\n    move 10 steps';if(/variable|score|counter/i.test(t))return 'when ▶ clicked\nset score to 0\nrepeat 5 times\n    change score by 1';if(/sensor|distance|button/i.test(t))return 'when board starts\nrepeat forever\n    if distance < 10\n        turn light on\n    else\n        turn light off';if(/function|python/i.test(t)||c.id==='university')return 'def greet(name):\n    return "Hello, " + name\n\nmessage = greet("Learner")\nprint(message)';if(c.id==='nursery')return 'when ▶ clicked\nmove 10 steps\nsay "Hello!"';return 'when ▶ clicked\nmove 10 steps\nturn 15 degrees\nsay "I made this!"'}
function challengeFor(t){return `Change one part of “${t}” so the result is different. Can you make a second version that still reaches the same goal? Explain which version is easier to understand.`}
function keyWords(t){if(/loop|repeat|pattern/i.test(t))return 'Loop · Repeat · Pattern';if(/if|choice|condition/i.test(t))return 'Condition · True · False · Choice';if(/variable|score|data/i.test(t))return 'Variable · Value · Update';if(/sensor|input/i.test(t))return 'Input · Sensor · Output';return 'Instruction · Program · Debug'}
function renderBlocks(){const cats=[...new Set(blockLabels.map(b=>b[1]))];$('#block-category').innerHTML='<option value="all">All categories</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');$('#block-stage').innerHTML='<option value="all">All stages</option>'+courses.slice(0,5).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('');filterBlocks()}
function filterBlocks(){const q=($('#block-search')?.value||'').toLowerCase(),cat=$('#block-category').value,stage=$('#block-stage').value;let list=blockLabels.filter(b=>(cat==='all'||b[1]===cat)&&(`${b[0]} ${b[1]} ${b[2]}`.toLowerCase().includes(q)));if(stage==='nursery')list=list.filter(b=>['Motion','Looks','Sound','Events','Control'].includes(b[1]));if(stage==='primary')list=list.filter(b=>!['AI','Video','Hardware'].includes(b[1]));$('#block-grid').innerHTML=list.length?list.map(b=>`<article class="block-card" data-add-block="${blockLabels.indexOf(b)}" tabindex="0" role="button" aria-label="Add ${esc(b[0])} to the preview"><div class="block-card-visual">${blockSvg(b[0],b[1],shapeForBlock(b[0],b[1]))}</div><h3>${esc(b[1])}</h3><p>${esc(b[2])}</p><div class="block-card-meta"><span>Click to add to preview</span></div></article>`).join(''):'<div class="empty-state">No blocks match that search. Try another word or category.</div>';renderLiveStack()}
