function renderProjects(){const filters=['All','Junior Blocks','Blocks','Blocks / Hardware','Python Editor','Robot Arm Studio'];$('#project-filters').innerHTML=filters.map(f=>`<button class="filter-chip ${projectFilter===f?'active':''}" data-filter="${esc(f)}">${esc(f)}</button>`).join('');const shown=projects.filter(p=>projectFilter==='All'||p[3].includes(projectFilter.replace(' / Hardware','')));$('#project-grid').innerHTML=shown.map(p=>`<article class="project-card"><span class="project-emoji">${p[0]}</span><h3>${esc(p[1])}</h3><p>${esc(p[2])}</p><span class="project-mode">${esc(p[3])}</span><span class="project-level">${esc(p[4])}</span><br><button class="inline-button" data-project-course="${p[3].includes('Python')?'university':p[3].includes('Robot')?'robotics':p[3].includes('Junior')?'primary':'lower'}">Explore the course →</button></article>`).join('')}
