function renderGlossary(){const q=($('#glossary-search')?.value||'').toLowerCase(),items=glossary.filter(x=>x.join(' ').toLowerCase().includes(q));$('#glossary-grid').innerHTML=items.map(x=>`<article class="glossary-card"><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></article>`).join('')||'<div class="empty-state">No matching words. Try another search.</div>'}
function doSearch(q){q=q.trim().toLowerCase();if(!q){$('#search-view').classList.add('hidden');$('#view-home').classList.add('active');return}$$('.view').forEach(v=>v.classList.remove('active'));$('#search-view').classList.remove('hidden');$('#search-title').textContent=`Results for “${q}”`;const results=[];courses.forEach(c=>{if((c.title+' '+c.summary+' '+c.mode+' '+c.grades).toLowerCase().includes(q))results.push({title:c.title+' course',sub:c.summary,action:()=>showCourse(c.id)});c.units.forEach((u,ui)=>u[1].forEach((l,li)=>{if((l+' '+u[0]).toLowerCase().includes(q))results.push({title:l,sub:`${c.title} · ${u[0]}`,action:()=>showLesson(c.id,ui,li)})}))});blockLabels.forEach(b=>{if(b.join(' ').toLowerCase().includes(q))results.push({title:b[0],sub:`Block Library · ${b[1]} — ${b[2]}`,action:()=>openView('blocks')})});glossary.forEach(g=>{if(g.join(' ').toLowerCase().includes(q))results.push({title:g[0],sub:g[1],action:()=>openView('glossary')})});$('#search-results').innerHTML=results.length?results.slice(0,35).map((r,i)=>`<article class="search-result" data-result="${i}"><strong>${esc(r.title)}</strong><small>${esc(r.sub)}</small></article>`).join(''):'<div class="empty-state">No matches yet. Try “loop”, “Python”, or “sensor”.</div>';$('#search-results')._results=results}
function showLesson(id,ui,li){const c=courses.find(x=>x.id===id);if(c){lessonReturnPage=currentBookPage;lessonMarkup(c,+ui,+li)}}
function saveProgress(){localStorage.setItem(storageKey,JSON.stringify([...completed]));renderHome();if(currentCourse)showCourse(currentCourse.id)}
function resetProgress(){if(confirm('Clear all lesson completion marks saved in this browser?')){completed.clear();localStorage.removeItem(storageKey);renderHome();toast('Your local progress has been reset.')}}
function bind(){document.addEventListener('click',e=>{const courseDownload=e.target.closest('[data-download-course]');if(courseDownload){downloadBookHtml(courseDownload.dataset.downloadCourse);return}const download=e.target.closest('[data-download-book]');if(download){downloadBookHtml();return}const readerControl=e.target.closest('[data-read-aloud]');if(readerControl){readBookPage(readerControl.dataset.readAloud);return}const page=e.target.closest('[data-book-page]');if(page){const targetPage=+page.dataset.bookPage;if(['primary','lower','upper','university','robotics'].includes(currentCourse?.id)&&targetPage>currentBookPage&&targetPage>=2){const isUniversity=currentCourse.id==='university',isRobotics=currentCourse.id==='robotics',isLower=currentCourse.id==='lower',isUpper=currentCourse.id==='upper',titles=isRobotics?roboticsProjectSectionTitles:isUniversity?universityProjectSectionTitles:isUpper?upperProjectSectionTitles:isLower?lowerProjectSectionTitles:primaryProjectSectionTitles,projects=isRobotics?roboticsProjectLessons:isUniversity?universityProjectLessons:isUpper?upperProjectLessons:isLower?lowerProjectLessons:primaryProjectLessons,targetProject=Math.floor((targetPage-2)/titles.length),firstIncomplete=projects.findIndex((_,index)=>!completed.has(currentCourse.id+':0:'+index));if(firstIncomplete>=0&&targetProject>firstIncomplete){toast('Complete Project '+(firstIncomplete+1)+' before moving on');return}}currentBookPage=targetPage;renderBookPage();return}const finish=e.target.closest('[data-mark-page]');if(finish){const [ui,li]=finish.dataset.markPage.split(':').map(Number),key=`${currentCourse.id}:${ui}:${li}`;completed.add(key);localStorage.setItem(storageKey,JSON.stringify([...completed]));renderBookPage();toast(['primary','lower','upper','university','robotics'].includes(currentCourse?.id)?'Project marked complete':'Page marked finished');return}const activity=e.target.closest('.lesson-open');if(activity){showLesson(activity.dataset.course,activity.dataset.unit,activity.dataset.lesson);return}const nav=e.target.closest('[data-view]');if(nav){openView(nav.dataset.view);return}const go=e.target.closest('[data-go]');if(go){openView(go.dataset.go);return}const card=e.target.closest('[data-course]');if(card&&!e.target.closest('.lesson-row')){showCourse(card.dataset.course);return}const row=e.target.closest('.lesson-row');if(row){showLesson(row.dataset.course,row.dataset.unit,row.dataset.lesson);return}const filter=e.target.closest('[data-filter]');if(filter){projectFilter=filter.dataset.filter;renderProjects();return}const project=e.target.closest('[data-project-course]');if(project){showCourse(project.dataset.projectCourse);return}const result=e.target.closest('[data-result]');if(result){const r=$('#search-results')._results?.[+result.dataset.result];r?.action();return}if(e.target.closest('[data-copy]')){const pre=e.target.closest('.code-sample');navigator.clipboard?.writeText(pre.innerText.replace('Copy example','').trim()).then(()=>toast('Example copied')).catch(()=>toast('Select and copy the example text'));return}});
 document.addEventListener('keydown',e=>{const card=e.target.closest('.path-card,.course-card');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showCourse(card.dataset.course)}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus()}});
 $$('.nav-link').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.view)));$('#back-course').onclick=()=>showCourse(currentCourse.id,lessonReturnPage);$('#reset-progress')?.addEventListener('click',resetProgress);$('#block-search')?.addEventListener('input',filterBlocks);$('#block-category')?.addEventListener('change',filterBlocks);$('#block-stage')?.addEventListener('change',filterBlocks);$('#glossary-search')?.addEventListener('input',renderGlossary);$('#global-search')?.addEventListener('input',e=>doSearch(e.target.value));$('#teacher-toggle')?.addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));document.body.classList.toggle('teacher-mode',on);toast(on?'Teacher notes are visible':'Teacher notes are hidden')});$('#lesson-content').addEventListener('click',e=>{if(e.target.id==='mark-complete'&&currentLesson){if(completed.has(currentLesson.key))completed.delete(currentLesson.key);else completed.add(currentLesson.key);localStorage.setItem(storageKey,JSON.stringify([...completed]));lessonMarkup(currentLesson.course,currentLesson.unitIndex,currentLesson.lessonIndex);toast(completed.has(currentLesson?.key)?'Lesson marked complete':'Lesson marked not complete')}if(e.target.id==='previous-lesson'||e.target.id==='next-lesson'){const delta=e.target.id==='next-lesson'?1:-1,at=currentLesson.all[currentLesson.pos+delta];if(at)showLesson(currentLesson.course.id,at.ui,at.li)}})}
function bindBlockLab(){
 const addBlock=b=>{if(b)window.blockPreview?.addBlock(b[0])};
 document.addEventListener('click',e=>{const preset=e.target.closest('[data-preset]');if(preset){setPreset(preset.dataset.preset);return}if(e.target.closest('#clear-stack')){window.blockPreview?.reset();return}const add=e.target.closest('[data-add-block]');if(add){addBlock(blockLabels[+add.dataset.addBlock])}});
 document.addEventListener('keydown',e=>{const card=e.target.closest('[data-add-block]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();addBlock(blockLabels[+card.dataset.addBlock])}})
}
